function saveSupplierMaster(array $data): array {
    $ref = consumeNextReference('supplier_master');

    $record = supabase_post(SB_API . 'm_suppliers', [
        'ref' => $ref,
        'supplier_name' => $data['supplier_name'] ?? '',
        'contact_person' => $data['contact_person'] ?? '',
        'phone' => $data['phone'] ?? '',
        'email' => $data['email'] ?? '',
        'supplier_category_ref' => !empty($data['supplier_category_ref']) ? $data['supplier_category_ref'] : null,
        'rate_card' => $data['rate_card'] ?? '',
        'created_by' => current_user()['ref'] ?? null,
        'updated_by' => current_user()['ref'] ?? null,
    ]);

    return $record;
}

function updateSupplierMaster(array $data): array {
    $ref = trim($data['ref'] ?? '');
    if ($ref === '' || !recordExists('m_suppliers', $ref)) {
        return ['error' => 'Record not found.'];
    }

    return supabase_patch(SB_API . 'm_suppliers?ref=eq.' . urlencode($ref), [
        'supplier_name' => $data['supplier_name'] ?? '',
        'contact_person' => $data['contact_person'] ?? '',
        'phone' => $data['phone'] ?? '',
        'email' => $data['email'] ?? '',
        'supplier_category_ref' => !empty($data['supplier_category_ref']) ? $data['supplier_category_ref'] : null,
        'rate_card' => $data['rate_card'] ?? '',
        'updated_by' => current_user()['ref'] ?? null,
    ]);
}

function listSupplierMaster(): array {
    return supabase_get(SB_API . 'm_suppliers?select=id,ref,supplier_name,contact_person,phone,email,supplier_category_ref,rate_card,m_supplier_categories(ref,supplier_category_name)&order=id.asc');
}

$action = $_GET['action'] ?? '';

if ($action === 'list') {
